import java.util.Arrays;

public class Solution {
    // O(V·E). Para cedo se uma rodada não muda nada.
    static long[] distancias(int n, int[][] arestas, int origem) {
        long[] d = new long[n];
        Arrays.fill(d, Long.MAX_VALUE);
        d[origem] = 0;
        for (int rodada = 0; rodada < n - 1; rodada++) {
            boolean mudou = false;
            for (int[] e : arestas) {
                if (d[e[0]] != Long.MAX_VALUE && d[e[0]] + e[2] < d[e[1]]) {
                    d[e[1]] = d[e[0]] + e[2];
                    mudou = true;
                }
            }
            if (!mudou) return d;
        }
        for (int[] e : arestas) if (d[e[0]] != Long.MAX_VALUE && d[e[0]] + e[2] < d[e[1]]) return null;
        return d;
    }
}

