        int[][] e = {{0, 1, 4}, {0, 2, 5}, {1, 2, -3}, {2, 3, 2}, {3, 1, 1}};
        assertArrayEquals(new long[]{0, 4, 1, 3}, Solution.distancias(4, e, 0));
    }

    @Test void cicloNegativoAlcancavel() {
        assertNull(Solution.distancias(3, new int[][]{{0, 1, 1}, {1, 2, -2}, {2, 1, 1}}, 0));
    }

    @Test void cicloNegativoInalcancavelNaoImporta() {
        long[] d = Solution.distancias(4, new int[][]{{0, 1, 2}, {2, 3, -5}, {3, 2, 1}}, 0);
        assertNotNull(d);
        assertEquals(2, d[1]);
        assertEquals(Long.MAX_VALUE, d[2]);
    }

    @Test void cadeiaLonga() {
        int n = 2000;
        int[][] e = new int[n - 1][];
        for (int i = 0; i + 1 < n; i++) e[i] = new int[]{n - 2 - i, n - 1 - i, -1}; // ordem ruim de propósito
        int[][] inv = new int[n - 1][];
        for (int i = 0; i < n - 1; i++) inv[i] = new int[]{i, i + 1, -1};
        assertEquals(-(n - 1), Solution.distancias(n, e, 0)[n - 1]);
        assertEquals(-(n - 1), Solution.distancias(n, inv, 0)[n - 1]);
    }
}

