import java.util.*;

public class Solution {
    static class Floyd {
        private static final long INF = Long.MAX_VALUE;
        private final long[][] d;
        private final int[][] next;

        Floyd(int n, int[][] arestas) {
            d = new long[n][n];
            next = new int[n][n];
            for (int i = 0; i < n; i++) {
                Arrays.fill(d[i], INF);
                Arrays.fill(next[i], -1);
                d[i][i] = 0;
                next[i][i] = i;
            }
            for (int[] e : arestas) {
                if (e[2] < d[e[0]][e[1]]) {
                    d[e[0]][e[1]] = e[2];
                    next[e[0]][e[1]] = e[1];
                }
            }
            // k fora: depois da iteração k, d[i][j] usa só intermediários em {0..k}.
            for (int k = 0; k < n; k++)
                for (int i = 0; i < n; i++) {
                    if (d[i][k] == INF) continue;
                    for (int j = 0; j < n; j++) {
                        if (d[k][j] == INF) continue;
                        if (d[i][k] + d[k][j] < d[i][j]) {
                            d[i][j] = d[i][k] + d[k][j];
                            next[i][j] = next[i][k];
                        }
                    }
                }
        }

        long dist(int u, int v) { return d[u][v]; }

        List<Integer> caminho(int u, int v) {
            if (next[u][v] == -1) return List.of();
            List<Integer> out = new ArrayList<>();
            out.add(u);
            while (u != v) {
                u = next[u][v];
                out.add(u);
            }
            return out;
        }
    }
}

