import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static final int[][] G = {{0, 1, 3}, {0, 2, 8}, {1, 2, -2}, {2, 3, 1}, {3, 0, 2}, {1, 3, 7}};

    @Test void distancias() {
        var f = new Solution.Floyd(4, G);
        assertEquals(1, f.dist(0, 2));
        assertEquals(2, f.dist(0, 3));
        assertEquals(3, f.dist(2, 0));
        assertEquals(0, f.dist(3, 3));
    }

    @Test void caminhos() {
        var f = new Solution.Floyd(4, G);
        assertEquals(List.of(0, 1, 2, 3), f.caminho(0, 3));
        assertEquals(List.of(2, 3, 0), f.caminho(2, 0));
        assertEquals(List.of(1), f.caminho(1, 1));
    }

    @Test void inalcancavel() {
        var f = new Solution.Floyd(3, new int[][]{{0, 1, 5}});
        assertEquals(Long.MAX_VALUE, f.dist(1, 0));
        assertEquals(List.of(), f.caminho(2, 0));
    }

    @Test void ordemDoKImporta() {
        // Com k no laço interno, este grafo dá resposta errada para 3 -> 0.
        int[][] e = {{3, 2, 1}, {2, 1, 1}, {1, 0, 1}, {3, 0, 100}};
        assertEquals(3, new Solution.Floyd(4, e).dist(3, 0));
    }

    @Test void trezentos() {
        int n = 300;
        int[][] e = new int[n][];
        for (int i = 0; i < n; i++) e[i] = new int[]{i, (i + 1) % n, 1};
        var f = new Solution.Floyd(n, e);
        assertEquals(n - 1, f.dist(1, 0));
        assertEquals(n, f.caminho(1, 0).size());
    }
}
